const financeFields={company:'Empresa solicitante',cnpj:'CNPJ da solicitante',representative:'Nome do representante',contact:'Contato do representante',number:'Número do documento',date:'Data',issuer:'Empresa prestadora',issuerCnpj:'CNPJ da prestadora',issuerContact:'Contato da prestadora',service:'Serviços executados',equipment:'Equipamentos / referências',amount:'Valor total',notes:'Observações',responsible:'Responsável pelo preenchimento',terms:'Condições / rodapé'};
function financeDB(){db.finance??={templates:[],documents:[]};if(!db.finance.templates.length){db.finance.templates=[{id:'default-os',name:'Ordem de serviço padrão',kind:'OS',mode:'standard',issuer:'',issuerCnpj:'',issuerContact:'',terms:'Serviços executados conforme descrição acima.'},{id:'default-nf',name:'Rascunho de nota padrão',kind:'NF',mode:'standard',issuer:'',issuerCnpj:'',issuerContact:'',terms:'Rascunho para conferência. Sem validade fiscal.'}];save()}return db.finance}
function financeStorage(){return new Promise((resolve,reject)=>{const req=indexedDB.open('bancada-documents',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(Error('Não foi possível acessar o armazenamento dos PDFs.'))})}
async function financeFile(key,value){const storage=await financeStorage();try{return await new Promise((resolve,reject)=>{const tx=storage.transaction('files',value===undefined?'readonly':'readwrite'),store=tx.objectStore('files');let result;const req=value===undefined?store.get(key):store.put(value,key);req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(Error('Não foi possível salvar o PDF. Verifique o espaço disponível no navegador.'));tx.onabort=()=>reject(Error('Armazenamento do PDF interrompido.'))})}finally{storage.close()}}
function financeError(e){toast(e.message||'Não foi possível concluir a operação.')}
function financeDownload(bytes,name){const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function financeInput(name,title,value='',options=''){return `<label>${title}<input name="${name}" value="${esc(value)}" ${options}></label>`}
function controladoria(){const f=financeDB();$('#content').innerHTML=heading('Controladoria','Prepare ordens de serviço e documentos a partir dos seus modelos.',`<button class="btn primary" id="newdocument">${icon('plus')} Novo documento</button>`)+`<div class="tabletitle"><h2>Modelos de documentos</h2><button class="link" id="newtemplate">+ Cadastrar modelo</button></div><div class="finance-templates">${f.templates.map(t=>`<section class="panel finance-template"><span class="eyebrow">${t.kind==='OS'?'ORDEM DE SERVIÇO':'RASCUNHO DE NOTA'}</span><h2>${esc(t.name)}</h2><p>Layout configurável · cabeçalho, logotipo e textos</p><div class="actions"><button class="link" data-template="${esc(t.id)}">Configurar modelo</button><button class="btn" data-use-template="${esc(t.id)}">Usar modelo →</button></div></section>`).join('')}</div><div class="tabletitle" style="margin-top:30px"><h2>Documentos gerados</h2><small>${f.documents.length} documento(s)</small></div><section class="panel"><div class="tablewrap"><table><thead><tr><th>DOCUMENTO</th><th>SOLICITANTE</th><th>REPRESENTANTE</th><th>DATA</th><th>RESPONSÁVEL</th><th></th></tr></thead><tbody>${f.documents.slice().reverse().map(d=>`<tr><td><b>${esc(d.number)}</b><small>${d.kind==='OS'?'Ordem de serviço':'Rascunho de nota'}</small></td><td>${esc(d.company)}<small>${esc(d.cnpj)}</small></td><td>${esc(d.representative)}<small>${esc(d.contact)}</small></td><td>${fmt(d.date)}</td><td>${esc(d.responsible)}</td><td><button class="link" data-download="${d.id}">Baixar PDF ↓</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhum documento gerado. Escolha um modelo para começar.</td></tr>'}</tbody></table></div></section><p class="note">Os modelos e PDFs ficam apenas neste navegador. A opção de nota gera um rascunho para conferência, sem emissão ou autorização fiscal.</p>`;$('#newdocument').onclick=()=>financeDocument();$('#newtemplate').onclick=()=>financeTemplate();document.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>financeTemplate(b.dataset.template));document.querySelectorAll('[data-use-template]').forEach(b=>b.onclick=()=>financeDocument(b.dataset.useTemplate));document.querySelectorAll('[data-download]').forEach(b=>b.onclick=async()=>{try{const bytes=await financeFile('doc:'+b.dataset.download);if(!bytes)throw Error('PDF não encontrado neste navegador.');const d=f.documents.find(d=>d.id===b.dataset.download);financeDownload(bytes,financeFilename(d))}catch(e){financeError(e)}})}
function financeFilename(d){return `${d.kind==='OS'?'OS':'RASCUNHO'}-${d.number.replace(/[^a-zA-Z0-9_-]/g,'_')}.pdf`}
async function financeTemplate(id){const existing=financeDB().templates.find(t=>t.id===id);let t=existing||{name:'',kind:'OS',mode:'standard',issuer:'',issuerCnpj:'',issuerContact:'',terms:'',mapping:{}};let imported=null,fields=[],newLogo=null;showModal(existing?'Configurar modelo':'Cadastrar modelo',`${financeInput('name','Nome do modelo',t.name,'required maxlength="80"')}<div class="formgrid"><label>Tipo de documento<select name="kind"><option value="OS" ${t.kind==='OS'?'selected':''}>Ordem de serviço</option><option value="NF" ${t.kind==='NF'?'selected':''}>Rascunho de nota fiscal</option></select></label><label hidden>Formato do modelo<select name="mode" id="templatemode"><option value="standard" ${t.mode==='standard'?'selected':''}>Layout padrão configurável</option><option value="pdf" ${t.mode==='pdf'?'selected':''}>Importar PDF preenchível</option></select></label></div>${financeInput('heading','Cabeçalho do documento',t.heading||'','maxlength="100" placeholder="Ex.: Assistência Técnica Multimarcas"')}<label>Logotipo (PNG ou JPG, até 500 KB)<input type="file" id="templatelogo" accept="image/png,image/jpeg"></label><p id="logoname" class="muted" style="font-size:12px;margin-bottom:16px">${esc(t.logoName||'Sem logotipo cadastrado.')}</p>${financeInput('issuer','Empresa prestadora',t.issuer,'maxlength="120"')}<div class="formgrid">${financeInput('issuerCnpj','CNPJ da prestadora',t.issuerCnpj,'maxlength="18"')}${financeInput('issuerContact','Contato da prestadora',t.issuerContact,'maxlength="120"')}</div><label>Condições / texto de rodapé<textarea name="terms" maxlength="1500">${esc(t.terms)}</textarea></label><div id="pdfconfig"><label>Arquivo PDF com campos de formulário<input type="file" id="pdftemplate" accept="application/pdf,.pdf"></label><small>Use um PDF preenchível de até 2 MB. Após carregar, associe os campos do seu PDF aos dados da console. PDFs sem campos precisam ser preparados como formulário antes da importação.</small><p class="muted" id="pdffilename" style="font-size:12px;margin:12px 0">${esc(t.filename||'Nenhum PDF selecionado.')}</p><div id="fieldmapping"></div></div>`,async f=>{const btn=$('#form button[type="submit"]')||$('#form .primary');btn.disabled=true;try{f.name=f.name.trim();if(!f.name)throw Error('Informe o nome do modelo.');if(f.mode==='pdf'){if(!imported&&!existing?.filename)throw Error('Selecione um PDF preenchível.');if(!fields.length)throw Error('Carregue um PDF com campos de texto.');f.mapping=Object.fromEntries(fields.map(name=>[name,$(`[data-map-index="${fields.indexOf(name)}"]`).value]).filter(([,key])=>key));for(const key of ['company','cnpj','representative','contact'])if(!Object.values(f.mapping).includes(key))throw Error('Associe empresa, CNPJ, representante e contato aos campos do PDF.')}const tid=t.id||crypto.randomUUID();if(imported)await financeFile('template:'+tid,imported.bytes);if(newLogo)await financeFile('logo:'+tid,newLogo.bytes);const next={...t,...f,id:tid,logoName:newLogo?.name||t.logoName||'',filename:f.mode==='pdf'?(imported?.name||t.filename):'',mapping:f.mapping||{}};if(existing)Object.assign(existing,next);else financeDB().templates.push(next);save();$('#modal').close();controladoria();toast('Modelo salvo.')}catch(e){$('#formerror').textContent=e.message}finally{btn.disabled=false}});$('#templatelogo').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>500*1024)throw Error('O logotipo deve ter até 500 KB.');const bytes=await file.arrayBuffer();const check=await PDFLib.PDFDocument.create();if(file.type==='image/png')await check.embedPng(bytes);else if(file.type==='image/jpeg')await check.embedJpg(bytes);else throw Error('Use logotipo PNG ou JPG.');newLogo={bytes,name:file.name};$('#logoname').textContent=file.name;$('#formerror').textContent=''}catch(err){newLogo=null;$('#formerror').textContent=err.message}};$('#templatemode').onchange=()=>$('#pdfconfig').hidden=$('#templatemode').value!=='pdf';$('#templatemode').onchange();function mappingUI(){ $('#fieldmapping').innerHTML=fields.map((name,i)=>`<label>Campo do PDF: ${esc(name)}<select data-map-index="${i}"><option value="">Deixar em branco</option>${Object.entries(financeFields).map(([key,label])=>`<option value="${key}" ${t.mapping?.[name]===key?'selected':''}>${label}</option>`).join('')}</select></label>`).join('')}
async function readPDF(bytes){const doc=await PDFLib.PDFDocument.load(bytes);const all=doc.getForm().getFields();if(all.some(f=>f instanceof PDFLib.PDFSignature))throw Error('Use um modelo sem campos de assinatura digital.');fields=all.filter(f=>f instanceof PDFLib.PDFTextField).map(f=>f.getName());if(!fields.length)throw Error('Este PDF não tem campos de texto preenchíveis. Prepare o arquivo como formulário ou use o layout padrão.');mappingUI()}
$('#pdftemplate').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2*1024*1024)throw Error('O PDF deve ter até 2 MB.');const bytes=await file.arrayBuffer();await readPDF(bytes);imported={bytes,name:file.name};$('#pdffilename').textContent=file.name;$('#formerror').textContent=''}catch(e){imported=null;fields=[];$('#fieldmapping').innerHTML='';$('#formerror').textContent=e.message}};if(t.mode==='pdf')try{const bytes=await financeFile('template:'+t.id);if(!bytes)throw Error('Modelo PDF não encontrado. Selecione o arquivo novamente.');await readPDF(bytes)}catch(e){$('#formerror').textContent=e.message}}
function financeDocument(templateId){const f=financeDB(),t=f.templates.find(t=>t.id===templateId)||f.templates[0];const number=String(f.documents.length+1).padStart(6,'0');showModal('Preparar documento',`<label>Modelo<select name="template" id="documenttemplate">${f.templates.map(m=>`<option value="${m.id}" ${m.id===t.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><div class="formgrid">${financeInput('number','Número do documento',number,'required maxlength="40"')}${financeInput('date','Data',today(),'type="date" required')}</div>${financeInput('company','Empresa solicitante','','required maxlength="150"')}<div class="formgrid">${financeInput('cnpj','CNPJ da solicitante','','required maxlength="18" placeholder="00.000.000/0000-00"')}${financeInput('representative','Nome do representante','','required maxlength="120"')}</div>${financeInput('contact','Contato do representante','','required maxlength="150" placeholder="Telefone e/ou e-mail"')}<label>Trazer dados de uma TV (opcional)<select id="documenttv"><option value="">Preencher manualmente</option>${db.tvs.map(v=>`<option value="${v.id}">OS ${esc(v.os)} · ${esc(v.model)} · ${esc(v.serial)}</option>`).join('')}</select></label><label>Equipamentos / referências<textarea name="equipment" maxlength="1500"></textarea></label><label>Serviços executados<textarea name="service" required maxlength="5000" rows="4"></textarea></label>${financeInput('amount','Valor total (R$)','','type="number" min="0" step="0.01" required')}<label>Observações<textarea name="notes" maxlength="2000"></textarea></label><p class="note" id="fiscalnote">${t.kind==='NF'?'Rascunho de nota, sem validade fiscal.':'Ordem de serviço conforme o modelo escolhido.'}</p><small>Responsável pelo preenchimento: ${esc(current.name)}</small>`,async values=>{const btn=$('#form .primary');btn.disabled=true;btn.textContent='Gerando PDF…';try{for(const key of ['number','company','cnpj','representative','contact','service']){values[key]=values[key].trim();if(!values[key])throw Error('Preencha todos os campos obrigatórios.')}if(!validCnpj(values.cnpj))throw Error('Informe um CNPJ válido.');const template=f.templates.find(t=>t.id===values.template);if(f.documents.some(d=>d.kind===template.kind&&d.number===values.number))throw Error('Já existe um documento desse tipo com este número.');const data={...values,id:crypto.randomUUID(),kind:template.kind,responsible:current.name,createdBy:current.login,amount:new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(values.amount)),heading:template.heading,issuer:template.issuer,issuerCnpj:template.issuerCnpj,issuerContact:template.issuerContact,terms:template.terms};const bytes=await financePDF(data,template);await financeFile('doc:'+data.id,bytes);f.documents.push(data);save();$('#modal').close();controladoria();financeDownload(bytes,financeFilename(data));toast('PDF gerado e salvo no histórico.')}catch(e){$('#formerror').textContent=e.message}finally{btn.disabled=false;btn.textContent='Gerar e baixar PDF'}});$('#form .primary').textContent='Gerar e baixar PDF';$('#documenttemplate').onchange=e=>{$('#fiscalnote').textContent=f.templates.find(t=>t.id===e.target.value).kind==='NF'?'Rascunho de nota, sem validade fiscal.':'Ordem de serviço conforme o modelo escolhido.'};$('#documenttv').onchange=e=>{const tv=db.tvs.find(v=>v.id===e.target.value);if(!tv)return;$('#form [name="equipment"]').value=`${tv.model} | Série: ${tv.serial} | OS: ${tv.os}`;$('#form [name="service"]').value=tv.serviceNotes||''}}
function validCnpj(value){const s=value.replace(/\D/g,'');if(s.length!==14||/^(\d)\1+$/.test(s))return false;const calc=n=>{let sum=0,weight=n-7;for(let i=0;i<n;i++){sum+=Number(s[i])*weight--;if(weight<2)weight=9}const r=sum%11;return r<2?0:11-r};return calc(12)===Number(s[12])&&calc(13)===Number(s[13])}
async function financePDF(data,template){const {PDFDocument,StandardFonts,rgb}=PDFLib;const safe=value=>String(value??'').replace(/[^\x09\x0A\x0D\x20-\x7E\xA0-\xFF]/g,'-');if(template.mode==='pdf'){const bytes=await financeFile('template:'+template.id);if(!bytes)throw Error('Arquivo do modelo não encontrado.');const doc=await PDFDocument.load(bytes),font=await doc.embedFont(StandardFonts.Helvetica),form=doc.getForm();for(const field of form.getFields())if(field instanceof PDFLib.PDFTextField)field.setText(safe(template.mapping[field.getName()]?(template.mapping[field.getName()]==='date'?fmt(data.date):data[template.mapping[field.getName()]]):''));form.updateFieldAppearances(font);form.flatten();if(data.kind==='NF'){for(const p of doc.getPages()){p.drawRectangle({x:0,y:0,width:p.getWidth(),height:23,color:rgb(1,.96,.88)});p.drawText('RASCUNHO - SEM VALIDADE FISCAL',{x:14,y:8,size:9,font,color:rgb(.55,.25,.1)})}}return doc.save()}
const doc=await PDFDocument.create(),font=await doc.embedFont(StandardFonts.Helvetica),bold=await doc.embedFont(StandardFonts.HelveticaBold);let logo=null;if(template.logoName){const bytes=await financeFile('logo:'+template.id);if(!bytes)throw Error('Logotipo não encontrado. Cadastre-o novamente no modelo.');const sig=new Uint8Array(bytes);logo=sig[0]===137?await doc.embedPng(bytes):await doc.embedJpg(bytes)}let page,y;const ink=rgb(.13,.20,.17),green=rgb(.09,.36,.27),muted=rgb(.45,.5,.47);function newPage(){page=doc.addPage([595.28,841.89]);y=790;if(logo){const factor=Math.min(130/logo.width,55/logo.height);page.drawImage(logo,{x:44,y:y-55,width:logo.width*factor,height:logo.height*factor});y-=75}if(data.heading){const header=safe(data.heading);const headerSize=Math.min(14,505/bold.widthOfTextAtSize(header,1));page.drawText(header,{x:44,y,size:headerSize,font:bold,color:green});y-=26}page.drawText(safe(data.kind==='OS'?'ORDEM DE SERVICO':'RASCUNHO DE NOTA'),{x:44,y,size:18,font:bold,color:green});y-=24;page.drawText(safe(`${data.number}  |  ${fmt(data.date)}`),{x:44,y,size:10,font,color:muted});y-=32}newPage();function line(text,b=false,size=10){if(y<70)newPage();page.drawText(safe(text),{x:44,y,size,font:b?bold:font,color:b?green:ink});y-=size+7}function wrap(text){const result=[];for(const paragraph of safe(text).split(/\r?\n/)){let current='';for(const word of paragraph.split(/\s+/)){if(font.widthOfTextAtSize(current+(current?' ':'')+word,10)>505){if(current)result.push(current);current='';let segment='';for(const ch of word){if(font.widthOfTextAtSize(segment+ch,10)>505){result.push(segment);segment=''}segment+=ch}current=segment}else current+=(current?' ':'')+word}result.push(current)}return result}function block(title,text){if(!text)return;if(y<115)newPage();y-=8;line(title.toUpperCase(),true,9);wrap(text).forEach(t=>line(t));y-=7}block('Prestadora',[data.issuer,data.issuerCnpj?`CNPJ: ${data.issuerCnpj}`:'',data.issuerContact].filter(Boolean).join('\n'));block('Empresa solicitante',`${data.company}\nCNPJ: ${data.cnpj}\nRepresentante: ${data.representative}\nContato: ${data.contact}`);block('Equipamentos / referências',data.equipment);block('Serviços executados',data.service);block('Valor total',data.amount);block('Observações',data.notes);block('Condições',data.terms);block('Responsável pelo preenchimento',data.responsible);if(data.kind==='NF')block('Rascunho - sem validade fiscal','Documento para conferência. Não representa emissão ou autorização de nota fiscal.');const pages=doc.getPages();pages.forEach((p,i)=>{p.drawLine({start:{x:44,y:46},end:{x:551,y:46},thickness:.5,color:rgb(.85,.89,.86)});p.drawText(`Bancada | ${data.kind==='OS'?'Ordem de servico':'Rascunho sem validade fiscal'} | ${i+1}/${pages.length}`,{x:44,y:30,size:8,font,color:muted})});return doc.save()}
